// Plain-language presentation of the existing evidence rules.
// These messages describe supplied raffle conditions, never a person's guilt.
export const quickExamples = {
  paid: 'Разыгрываем новый смартфон! Для участия обязательно оплатите билет за 3 000 тенге. Победителя определит колесо фортуны. Продажа слотов открыта. Комиссия организатора — 10%.',
  free: 'Разыгрываем книгу среди подписчиков. Участие бесплатное, без покупки и без взносов. Победителя выберем случайно из комментариев.',
};

export function consumerVerdict(campaign) {
  const a=campaign.analysis, s=a.signals;
  if(a.risk==='high') return {
    tone:'danger', icon:'alert', label:'Платное участие + случайный выбор',
    title:'Есть признаки платной лотереи.',
    description:s.income.state==='found'?'Найдены приз, обязательная оплата, случайный выбор и заявление о доходе или комиссии организатора. Сверьте эти условия по первоисточникам.':'Найдены приз, обязательная оплата и случайный выбор. Доход организатора пока не подтверждён; оплата не гарантирует вам выигрыш.',
    short:'Есть платное участие и случайный выбор',
    actionTitle:'Что сделать сейчас',
    actions:['Уточните, кому и на каких условиях предлагают перевести деньги.','Сохраните полные правила, публикации и материалы эфира.','Добавьте другие розыгрыши этого аккаунта, чтобы увидеть повторяемость.'],
  };
  if(a.contradictions.length) return {
    tone:'caution', icon:'alert', label:'Условия не сходятся',
    title:'Сначала уточните условия.',
    description:'В материалах есть противоречия. По ним нельзя сделать уверенный вывод. Уточните действующие правила до оплаты.',
    short:'Есть противоречия в условиях',
    actionTitle:'Что уточнить', actions:a.contradictions,
  };
  if(s.free.state==='found'&&s.payment.state==='unknown') return {
    tone:'calm', icon:'shield', label:'Обязательная оплата не найдена',
    title:'Оплаты за участие не видно.',
    description:'В тексте заявлено бесплатное участие. По этим материалам не найдено сочетание признаков платного розыгрыша.',
    short:'В тексте заявлено бесплатное участие',
    actionTitle:'На что обратить внимание',
    actions:['Если позже попросят деньги, добавьте новое сообщение в проверку.','Не передавайте коды из SMS и данные карты.'],
  };
  if(s.warning.state==='found'&&['prize','payment','random'].every(k=>s[k].state==='unknown')) return {
    tone:'neutral', icon:'info', label:'Нужен текст самого предложения',
    title:'Это похоже на предупреждение.',
    description:'В тексте обсуждается подозрительное предложение. Добавьте сам пост или сообщение с условиями розыгрыша.',
    short:'Загружено предупреждение или разбор',
    actionTitle:'Что добавить', actions:['Текст оригинального предложения или скриншот его условий.'],
  };
  const asks=[];
  if(s.prize.state==='unknown') asks.push('Что именно обещают разыграть?');
  if(s.payment.state==='unknown') asks.push('Нужно ли платить, покупать билет или товар, чтобы участвовать?');
  if(s.random.state==='unknown') asks.push('Как выбирают победителя: случайно, жюри или другим способом?');
  return {
    tone:'caution', icon:'info', label:'Условий недостаточно',
    title:'Пока не всё понятно.',
    description:s.payment.state==='found'?'Оплата упоминается, но остальных условий недостаточно. Не спешите с переводом — сначала соберите полные правила.':'По этим материалам нельзя уверенно оценить розыгрыш. Добавьте недостающие условия.',
    short:'Для вывода нужны дополнительные условия',
    actionTitle:'Чего не хватает',actions:asks.length?asks:['Добавьте полный текст условий розыгрыша.'],
  };
}
